validator:
function validate(input) {
  const [{ Candidates = [], Projects = [] }] = input;
  for (const [table, rows] of [['Candidates', Candidates], ['Projects', Projects]]) {
    const keys = new Set();
    for (const [id, skill, level] of rows) {
      if (id === null || skill === null || level === null) return `${table} rows may not contain null.`;
      if (level < 1 || level > 5) return `${table} levels must be from 1 to 5.`;
      const key = `${id}|${skill.toLowerCase()}`;
      if (keys.has(key)) return `${table} lists skill ${skill} twice for ${id}.`;
      keys.add(key);
    }
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const small = size === 'small';
  const skills = small ? ['Python', 'SQL', 'R', 'Spark', 'Tableau'] : ['Python', 'SQL', 'R', 'Spark', 'Tableau', 'Excel', 'Java', 'Scala'];
  const subset = (count) => {
    const pool = [...skills];
    for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
    return pool.slice(0, count);
  };
  const Candidates = [], Projects = [];
  // Small cases: few skills and levels, so eligibility gaps and score ties are common.
  const people = small ? pick(4) : 300, projects = small ? 1 + pick(3) : 200;
  for (let i = 0; i < people; i++) {
    const id = small ? 101 + 2 * i + pick(2) : 1000 + i;
    for (const skill of subset(small ? 1 + pick(4) : 4)) if (!small || Candidates.length < 8) Candidates.push([id, skill, 1 + pick(5)]);
  }
  for (let i = 0; i < projects; i++) {
    const id = small ? 501 + 3 * i + pick(3) : 5000 + i;
    for (const skill of subset(1 + pick(3))) if (!small || Projects.length < 8) Projects.push([id, skill, 1 + pick(5)]);
  }
  for (const rows of [Candidates, Projects]) for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ Candidates, Projects }];
}
